def forwards(apps, schema_editor):
    """Перенос со схемы «этапы + доля рабочего в платеже» на «одна цена + выплаты рабочему»."""
    Project = apps.get_model('core', 'Project')
    Payment = apps.get_model('core', 'Payment')
    WorkerPayout = apps.get_model('core', 'WorkerPayout')
    stage_names = {'start': 'Старт', 'beta': 'Бета', 'final': 'Сдача'}

    for pr in Project.objects.all():
        if pr.has_stages:
            pr.price = sum((v or Decimal('0')) for v in (pr.start_amount, pr.beta_amount, pr.final_amount))
        pr.worker_amount = (pr.worker_beta_amount or Decimal('0')) + (pr.worker_final_amount or Decimal('0'))
        pr.save(update_fields=['price', 'worker_amount'])

    # доля рабочего, удержанная из старых платежей, становится выплатой рабочему;
    # компания получает эти деньги в платёж и тут же расходует — баланс не меняется
    for pay in Payment.objects.filter(worker_amount__gt=0).select_related('project'):
        WorkerPayout.objects.create(
            project=pay.project, worker_id=pay.project.worker_id, amount=pay.worker_amount,
            date=pay.date, paid_from='company',
            note=f'Доля за этап «{stage_names.get(pay.kind, pay.kind)}» (перенесено из старой схемы)')
        pay.company_amount += pay.worker_amount
        pay.worker_amount = Decimal('0')
        pay.save(update_fields=['company_amount', 'worker_amount'])


